+    false
+  } else {
+    try {
+      let environment = @json.parse(
+        @fs.read_file(directory + "/environment.json").text(),
+      )
+      recording_from_environment(environment)
+    } catch {
+      error => if @async.is_being_cancelled() { raise error } else { false }
+    }
+  }
