106	fn diagnostic_json(
107	  value : Json,
108	  environment : Map[String, String],
109	  protected_secrets : Array[String],
110	  truncated : Ref[Bool],
111	  depth : Int32,
112	) -> Json {
113	  if depth >= 64 {
114	    truncated.val = true
115	    return Json::string("[nested evidence omitted]")
116	  }
117	  match value {
118	    Json::Object(values) => {
119	      let result = Json::empty_object()
120	      for name, item in values {
121	        let key = name.to_lower().replace_all(old="_", new="")
122	        let safe_name = diagnostic_text(name, environment~, protected_secrets~)
123	        if field(result, safe_name) is Some(_) {
124	          truncated.val = true
125	          continue
126	        }
127	        if safe_name.has_suffix("\n[error details incomplete or truncated]") {
128	          truncated.val = true
129	        }
130	        set_field(
131	          result,
132	          safe_name,
133	          if credential_field(name) || key == "pairingcode" {
134	            Json::string("[redacted]")
135	          } else {
136	            diagnostic_json(
137	              item,
138	              environment,
139	              protected_secrets,
140	              truncated,
141	              depth + 1,
142	            )
143	          },
144	        )
145	      }
146	      result
147	    }
148	    Json::Array(values) =>
149	      Json::array(
150	        values.map(item => {
151	          diagnostic_json(
152	            item,
153	            environment,
154	            protected_secrets,
155	            truncated,
156	            depth + 1,
157	          )
158	        }),
159	      )
160	    Json::String(text) => {
161	      let safe = diagnostic_text(text, environment~, protected_secrets~)
162	      if safe.has_suffix("\n[error details incomplete or truncated]") {
163	        truncated.val = true
164	      }
