172	async fn diagnostic_retained_records(file : @fs.File, size : Int64) -> String {
173	  let length = if size > 262144L { 262144 } else { size.to_int() }
174	  let bytes = FixedArray::make(length, b'\x00')
175	  let read = file.read_at(bytes, position=size - length.to_int64())
176	  let text = @utf8.decode_lossy(bytes.unsafe_reinterpret_as_bytes()[:read])
177	  let lines = text.split("\n").to_array()
178	  let kept = FixedArray::make(lines.length(), false)
179	  let mut remaining = 65536
180	  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
181	    if i == 0 && size > length.to_int64() {
182	      continue
183	    }
184	    let length = lines[i].length() + 1
185	    if length <= remaining {
186	      kept[i] = true
187	      remaining -= length
188	    }
189	  }
190	  remaining = 65536
191	  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
192	    if kept[i] || (i == 0 && size > length.to_int64()) {
193	      continue
194	    }
195	    let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
196	    let failed = field(event, "errorType") is Some(_) ||
197	      (match field(event, "status") {
198	        Some(Json::String(status)) =>
199	          ["failed", "timeout", "cancelled", "warning", "process-error"].contains(
200	            status,
201	          )
202	        _ => false
203	      })
204	    let length = lines[i].length() + 1
205	    if failed && length <= remaining {
206	      kept[i] = true
207	      remaining -= length
208	    }
209	  }
210	  let result = @buffer.Buffer(size_hint=131072)
211	  for i in 0..<lines.length() {
212	    if kept[i] {
213	      result.write_string_utf8(lines[i].to_owned() + "\n")
214	    }
215	  }
216	  @utf8.decode_lossy(result.to_bytes())
217	}
