220	async fn save_diagnostic(
221	  stage : String,
222	  status : String,
223	  exit_code? : Int32,
224	  error_type? : String,
225	  phase? : String,
226	  duration_ms? : Double,
227	  attempt? : Int32,
228	  retry_delay_ms? : Int32,
229	  timeout_ms? : Int32,
230	  os_errno? : Int32,
231	  source? : CreateEvidence,
232	  error_message? : String,
233	  details_truncated~ : Bool = false,
234	  tunnel_directory? : String,
235	  expected_workspace_uid? : String,
236	  observed_workspace_uid? : String,
237	  evidence? : Json,
238	  recording? : Bool,
239	  environment? : Map[String, String],
240	  protected_secrets? : Array[String],
241	) -> Unit {
242	  if !recording.unwrap_or(
243	      @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0"),
244	    ) {
245	    return
246	  }
247	  let event : Json = {
248	    "stage": stage,
249	    "status": status,
250	    "time": @env.now().to_string(),
251	    "runId": recording_run_id,
252	    "adapterVersion": version,
253	  }
254	  if create_recording.attempt > 0 {
255	    set_field(
256	      event,
257	      "createAttempt",
258	      Json::number(create_recording.attempt.to_double()),
259	    )
260	    set_field(event, "createPhase", Json::string(create_recording.phase))
261	  }
262	  let process_environment = @env.get_env_vars()
263	  let secrets = [] + protected_secrets.unwrap_or([])
264	  if environment is Some(environment) {
265	    for secret in Progress::new("diagnostic-evidence", environment~).secrets {
266	      secrets.push(secret)
267	    }
268	  }
269	  if tunnel_directory is Some(directory) &&
270	    diagnostic_workspace_environments.get(directory) is Some(environment) {
271	    for secret in Progress::new("diagnostic-evidence", environment~).secrets {
272	      secrets.push(secret)
273	    }
274	  }
275	  if error_message is Some(message) {
276	    let message = diagnostic_text(
277	      message,
278	      environment=process_environment,
279	      protected_secrets=secrets,
280	    )
281	    set_field(event, "errorMessage", Json::string(message))
282	    set_field(
283	      event,
284	      "detailsTruncated",
285	      Json::boolean(
286	        details_truncated ||
287	        message.has_suffix("\n[error details incomplete or truncated]"),
288	      ),
289	    )
290	  }
291	  if tunnel_directory is Some(directory) {
292	    set_field(
293	      event,
294	      "tunnelDirectory",
295	      Json::string(
296	        diagnostic_text(
297	          directory,
298	          environment=process_environment,
299	          protected_secrets=secrets,
300	        ),
301	      ),
302	    )
303	  }
304	  for
305	    pair in [
306	      ("expectedWorkspaceUid", expected_workspace_uid),
307	      ("observedWorkspaceUid", observed_workspace_uid),
308	    ] {
309	    if pair.1 is Some(value) {
310	      set_field(
311	        event,
312	        pair.0,
313	        Json::string(
314	          diagnostic_text(
315	            value,
316	            environment=process_environment,
317	            protected_secrets=secrets,
318	          ),
319	        ),
320	      )
321	    }
322	  }
323	  let evidence_truncated : Ref[Bool] = { val: false, }
324	  if source is Some(evidence) {
325	    set_field(
326	      event,
327	      "source",
328	      diagnostic_json(
329	        evidence.to_json(),
330	        process_environment,
331	        secrets,
332	        evidence_truncated,
333	        0,
334	      ),
335	    )
336	  }
337	  if evidence is Some(value) {
338	    if value.stringify().length() <= 65536 {
339	      set_field(
340	        event,
341	        "evidence",
342	        diagnostic_json(
343	          value, process_environment, secrets, evidence_truncated, 0,
344	        ),
345	      )
346	    } else {
347	      evidence_truncated.val = true
348	    }
349	  }
350	  if evidence_truncated.val {
351	    set_field(event, "evidenceTruncated", Json::boolean(true))
352	    set_field(event, "completeness", Json::string("partial"))
353	  }
354	  if os_errno is Some(code) && code > 0 && code < 4096 {
355	    set_field(event, "osErrno", Json::number(code.to_double()))
356	  }
357	  if exit_code is Some(code) {
358	    set_field(event, "exitCode", Json::number(code.to_double()))
359	  }
360	  for pair in [("errorType", error_type), ("phase", phase)] {
361	    if pair.1 is Some(text) {
362	      set_field(event, pair.0, Json::string(text))
363	    }
364	  }
365	  if duration_ms is Some(value) {
366	    set_field(event, "durationMs", Json::number(value))
367	  }
368	  if attempt is Some(value) {
369	    set_field(event, "attempt", Json::number(value.to_double()))
370	  }
371	  if timeout_ms is Some(value) {
372	    set_field(event, "timeoutMs", Json::number(value.to_double()))
373	  }
374	  if retry_delay_ms is Some(value) {
375	    set_field(event, "retryDelayMs", Json::number(value.to_double()))
376	  }
377	  let failed = error_type is Some(_) ||
378	    ["failed", "timeout", "cancelled", "warning", "process-error"].contains(
379	      status,
380	    )
381	  if diagnostic_pending.length() >= 64 {
382	    let mut evict = -1
383	    if failed {
384	      for index in diagnostic_pending_inflight.val..<diagnostic_pending.length() {
385	        if !diagnostic_pending[index].failed {
386	          evict = index
387	          break
388	        }
389	      }
390	      if evict < 0 &&
391	        diagnostic_pending_inflight.val < diagnostic_pending.length() {
392	        evict = diagnostic_pending_inflight.val
393	      }
394	    }
395	    if evict < 0 {
396	      diagnostic_recording_failed("buffer_full", phase="buffer")
397	      return
398	    }
399	    ignore(diagnostic_pending.remove(evict))
400	    diagnostic_pending.push({ event, failed, })
401	    diagnostic_recording_failed("buffer_full", phase="buffer")
402	    try_flush_diagnostic_recording()
403	    return
404	  }
405	  diagnostic_pending.push({ event, failed, })
406	  try_flush_diagnostic_recording()
407	}
