635	///|
636	fn diagnostic_text(
637	  message : String,
638	  environment? : Map[String, String],
639	  omitted~ : Bool = false,
640	  protected_values? : Array[String],
641	  protected_secrets? : Array[String],
642	  incomplete_final_line~ : Bool = false,
643	) -> String {
644	  let progress = Progress::new("diagnostic-error", environment?)
645	  if protected_values is Some(values) {
646	    for value in values {
647	      if value != "" {
648	        if value.length() < 4 {
649	          progress.short_values.push(value)
650	        } else {
651	          progress.secrets.push(value)
652	        }
653	      }
654	    }
655	  }
656	  if protected_secrets is Some(values) {
657	    for value in values {
658	      if value != "" {
659	        progress.secrets.push(value)
660	        for line in value.split("\n") {
661	          if line.trim() != "" && line.length() < value.length() {
662	            progress.secrets.push(line.to_owned())
663	          }
664	        }
665	      }
666	    }
667	  }
668	  progress.secrets.sort_by((a, b) => b.length().compare(a.length()))
669	  let lines = []
670	  let mut incomplete = omitted
671	  let source_lines = message.split("\n").to_array()
672	  for index in 0..<source_lines.length() {
673	    let line = source_lines[index]
674	    if lines.length() == 32 {
675	      incomplete = true
676	      ignore(lines.remove(1))
677	    }
678	    let truncated = line.length() > 1024
679	    let bounded = if truncated {
680	      incomplete = true
681	      line[:1024].to_owned()
682	    } else {
683	      line.to_owned()
684	    }
685	    let bounded = if truncated ||
686	      (incomplete_final_line && index == source_lines.length() - 1) {
687	      diagnostic_partial_secret(
688	        bounded,
689	        progress.secrets + progress.short_values,
690	      )
691	    } else {
692	      bounded
693	    }
694	    match progress.safe_message(bounded) {
695	      Some(safe) => lines.push(safe)
696	      None => {
697	        incomplete = true
698	        lines.push("[unavailable]")
699	      }
700	    }
701	  }
702	  if (incomplete || progress.details_truncated) &&
703	    lines.last() != Some("[error details incomplete or truncated]") {
704	    lines.push("[error details incomplete or truncated]")
705	  }
706	  lines.join("\n")
707	}
