709	///|
710	fn diagnostic_partial_secret(text : String, secrets : Array[String]) -> String {
711	  let chars = text.iter().to_array()
712	  let mut boundary = chars.length()
713	  for secret in secrets {
714	    let value = secret.iter().to_array()
715	    if value.length() == 0 || text.has_suffix(secret) {
716	      continue
717	    }
718	    let limit = if value.length() - 1 < boundary {
719	      value.length() - 1
720	    } else {
721	      boundary
722	    }
723	    if limit == 0 {
724	      continue
725	    }
726	    let prefixes = FixedArray::make(limit, 0)
727	    let mut matched = 0
728	    for index in 1..<limit {
729	      while matched > 0 && value[matched] != value[index] {
730	        matched = prefixes[matched - 1]
731	      }
732	      if value[matched] == value[index] {
733	        matched += 1
734	      }
735	      prefixes[index] = matched
736	    }
737	    matched = 0
738	    for index in 0..<boundary {
739	      while matched > 0 && (matched == limit || value[matched] != chars[index]) {
740	        matched = prefixes[matched - 1]
741	      }
742	      if matched < limit && value[matched] == chars[index] {
743	        matched += 1
744	      }
745	    }
746	    boundary -= matched
747	  }
748	  if boundary == chars.length() {
749	    text
750	  } else {
751	    character_text(chars, 0, boundary) + "[redacted]"
752	  }
753	}
