 86	///|
 87	async fn host_orca_settings() -> String {
 88	  let (executable, resources, user_data) = host_orca_location()
 89	  let env = @env.get_env_vars()
 90	  env.set("ELECTRON_RUN_AS_NODE", "1")
 91	  env.remove("NODE_OPTIONS")
 92	  env.remove("NODE_REPL_EXTERNAL_MODULE")
 93	  settings_process(
 94	    executable,
 95	    ["-e", orca_settings_script(), "--", "export", resources, user_data],
 96	    environment=env,
 97	  )
 98	}
