100	///|
101	async fn settings_process(
102	  program : String,
103	  args : Array[String],
104	  environment~ : Map[String, String],
105	  input? : String,
106	) -> String {
107	  let (stdin, writer) = @process.write_to_process()
108	  defer writer.close()
109	  @async.with_task_group(async fn(group) {
110	    let output = group.spawn(async fn() {
111	      diagnostic_process_output(
112	        program,
113	        args,
114	        environment~,
115	        stdin~,
116	        stdout_limit=4194304,
117	        stderr_limit=8192,
118	      )
119	    })
120	    let write_error = try {
121	      if input is Some(value) {
122	        writer.write(value)
123	      }
124	      None
125	    } catch {
126	      error =>
127	        if @async.is_being_cancelled() {
128	          raise error
129	        } else {
130	          Some(error)
131	        }
132	    }
133	    writer.close()
134	    let (status, stdout, stdout_truncated, stderr, stderr_truncated) = if write_error
135	      is Some(error) {
136	      @async.with_timeout(1000, async fn() { output.wait() }) catch {
137	        wait_error => {
138	          if @async.is_being_cancelled() {
139	            raise wait_error
140	          }
141	          raise AdapterError(
142	            "Orca settings input transfer failed; process exit unavailable: " +
143	            diagnostic_error(error, environment~),
144	          )
145	        }
146	      }
147	    } else {
148	      output.wait()
149	    }
150	    guard status == 0 else {
151	      let mut phase = "process"
152	      let mut code = "process_exit"
153	      let mut detail = diagnostic_output(
154	        stderr,
155	        environment,
156	        protected_input?=input,
157	        omitted=stderr_truncated,
158	      )
159	      if !stderr_truncated {
160	        try {
161	          let error = @json.parse(@utf8.decode(stderr))
162	          let reported_phase = required(error, "phase")
163	          let reported_code = required(error, "code")
164	          if [
165	              "load", "read", "normalize", "input", "profile", "write", "verify",
166	            ].contains(reported_phase) &&
167	            ["EACCES", "ENOENT", "EBUSY", "ENOSPC", "INCOMPATIBLE", "INVALID"].contains(
168	              reported_code,
169	            ) {
170	            phase = reported_phase
171	            code = reported_code
172	            let kind = match field(error, "kind") {
173	              Some(Json::String(value)) if [
174	                  "Error", "TypeError", "SyntaxError", "ReferenceError", "RangeError",
175	                  "AssertionError", "URIError",
176	                ].contains(value) => Some(value)
177	              _ => None
178	            }
179	            let native_code = match field(error, "nativeCode") {
180	              Some(Json::String(value)) if value.length() > 0 &&
181	                value.length() <= 64 &&
182	                value
183	                .iter()
184	                .all(c => {
185	                  (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_'
186	                }) => Some(value)
187	              _ => None
188	            }
189	            detail = if kind is Some(kind) {
190	              Some(
191	                kind +
192	                native_code.map(value => " (" + value + ")").unwrap_or(""),
193	              )
194	            } else {
195	              None
196	            }
197	            for
198	              name in (if native_code == Some("MODULE_NOT_FOUND") {
199	                ["target", "missing", "cause", "location"]
200	              } else {
201	                ["target", "cause", "location"]
202	              }) {
203	              if field(error, name) is Some(Json::String(value)) &&
204	                value.length() > 0 &&
205	                value.length() <= 1024 &&
206	                diagnostic_output(
207	                  @utf8.encode(value),
208	                  environment,
209	                  protected_input?=input,
210	                )
211	                is Some(safe) {
212	                detail = Some(
213	                  detail.unwrap_or("Error") + " " + name + "=" + safe,
214	                )
215	              }
216	            }
217	          }
218	        } catch {
219	          _ => ()
220	        }
221	      }
222	      if write_error is Some(error) {
223	        detail = Some(
224	          detail.unwrap_or("Process exited without readable stderr") +
225	          "\nInput transfer failed: " +
226	          diagnostic_error(error, environment~),
227	        )
228	      }
229	      raise SettingsProcessError(phase, code, status, detail)
230	    }
231	    if write_error is Some(error) {
232	      raise error
233	    }
234	    guard !stdout_truncated else {
235	      raise AdapterError("Orca settings result exceeds size limit")
236	    }
237	    @utf8.decode(stdout)
238	  })
239	}
