252	    phase = "remote"
253	    let script = "unset NODE_OPTIONS NODE_REPL_EXTERNAL_MODULE; ORCA_USER_DATA_PATH=/worktrees/.orca ELECTRON_RUN_AS_NODE=1 \"$HOME/.local/share/orca-env-devsy/orca/current/orca-ide\" -e " +
254	      quote(orca_settings_script()) +
255	      " -- import \"$HOME/.local/share/orca-env-devsy/orca/current/resources\" /worktrees/.orca"
256	    let env = workspace_environment(state)
257	    ignore(
258	      settings_process(
259	        workspace_program(state, "ssh"),
260	        mux_ssh_args(state) + [script],
261	        environment=env,
262	        input=payload,
263	      ),
264	    )
265	  }) catch {
266	    SettingsProcessError(helper_phase, code, status, detail) => {
267	      save_diagnostic(
268	        "orca-settings",
269	        "failed",
270	        phase=phase + "/" + helper_phase,
271	        error_type=code,
272	        exit_code=status,
273	        error_message?=detail,
274	        recording=operation_recording(state),
275	      )
276	      raise AdapterError(
277	        "Orca settings transfer failed (exit \{status}, " +
278	        phase +
279	        "/" +
280	        helper_phase +
281	        ": " +
282	        code +
283	        ")",
284	      )
285	    }
286	    @async.TimeoutError as error => {
287	      save_diagnostic(
288	        "orca-settings",
289	        "timeout",
290	        phase~,
291	        error_type="timeout",
292	        recording=operation_recording(state),
293	      )
294	      raise error
295	    }
296	    error => {
297	      let detail = diagnostic_error(
298	        error,
299	        environment=workspace_environment(state),
300	      )
301	      save_diagnostic(
302	        "orca-settings",
303	        if @async.is_being_cancelled() {
304	          "cancelled"
305	        } else {
306	          "failed"
307	        },
308	        phase~,
309	        error_type=if error is AdapterError(_) {
310	          "settings_source"
311	        } else {
312	          "settings_transfer"
313	        },
314	        error_message=detail,
315	        recording=operation_recording(state),
316	      )
317	      raise error
318	    }
319	  }
320	  save_diagnostic(
321	    "orca-settings",
322	    "success",
323	    phase~,
324	    recording=operation_recording(state),
325	  )
326	  progress_message("orca-settings: done")
327	}
