 222	fn workspace_environment(state : Json) -> Map[String, String] {
 223	  let environment = match field(state, "executionEnvironment") {
 224	    Some(Json::Object(values)) => {
 225	      let result : Map[String, String] = Map([])
 226	      for (name, value) in values {
 227	        if value is Json::String(value) {
 228	          result.set(name, value)
 229	        }
 230	      }
 231	      result
 232	    }
 233	    _ => @env.get_env_vars()
 234	  }
 235	  for name in location_variables {
 236	    match field(field(state, "devsyEnv").unwrap_or(Json::null()), name) {
 237	      Some(Json::String(value)) => environment.set(name, value)
 238	      _ => environment.remove(name)
 239	    }
 240	  }
