 252	///|
 253	async fn workspace_program(state : Json, program : String) -> String {
 254	  let cwd = workspace_directory(state).unwrap_or(
 255	    @env.current_dir().unwrap_or("/"),
 256	  )
 257	  if program.has_prefix("/") {
 258	    return program
 259	  }
 260	  if program.contains("/") {
 261	    return cwd + "/" + program
 262	  }
 263	  let path = field(field(state, "devsyEnv").unwrap_or(Json::null()), "PATH")
 264	  let path = match path {
 265	    Some(Json::String(value)) => value
 266	    _ => "/usr/bin:/bin"
 267	  }
 268	  let mut fallback = None
 269	  for directory in path.split(":") {
 270	    let directory = if directory.has_prefix("/") {
 271	      directory.to_owned()
 272	    } else {
 273	      cwd + "/" + directory.to_owned()
 274	    }
 275	    let candidate = directory + "/" + program
 276	    if fallback is None {
 277	      fallback = Some(candidate)
 278	    }
 279	    if transport_access(@utf8.encode(candidate + "\u0000"), 1) == 0 &&
 280	      @fs.kind(candidate) != @fs.FileKind::Directory {
 281	      return candidate
 282	    }
 283	  }
 284	  fallback.unwrap_or(cwd + "/" + program)
 285	}
