  34	///|
  35	async fn command_result(
  36	  program : String,
  37	  args : Array[String],
  38	  stage : String,
  39	  environment? : Map[String, String],
  40	  cwd? : StringView,
  41	  target? : String,
  42	  recording_override? : Bool,
  43	) -> (Int32, String, String) {
  44	  let recording = recording_override.unwrap_or(
  45	    environment.unwrap_or(@env.get_env_vars()).get("ORCA_ENV_DEVSY_RECORDING") !=
  46	    Some("0"),
  47	  )
  48	  save_diagnostic(stage, "started", recording~)
  49	  let started = @env.now()
  50	  let progress = Progress::new(
  51	    stage,
  52	    environment?,
  53	    recording_override=recording,
  54	  )
  55	  let label = target.map(value => value + ": " + stage).unwrap_or(stage)
  56	  progress_message(label + ": running…")
  57	  let mut failure_kind = "process_api"
  58	  let mut failure_errno = None
  59	  let mut failure_phase = None
  60	  let (status, output, errors) = {
  61	    errdefer {
  62	      save_diagnostic(
  63	        stage,
  64	        if @async.is_being_cancelled() {
  65	          "cancelled"
  66	        } else {
  67	          "process-error"
  68	        },
  69	        error_type=failure_kind,
  70	        os_errno?=failure_errno,
  71	        phase?=failure_phase,
  72	        error_message=progress.failure_detail(),
  73	        details_truncated=progress.details_truncated,
  74	        recording~,
  75	      )
  76	      progress_message(label + ": failed (" + progress_timing(started) + ")")
  77	    }
  78	    try {
  79	      let (out, stdout) = @process.read_from_process()
  80	      defer out.close()
  81	      let (err, stderr) = @process.read_from_process()
  82	      defer err.close()
  83	      @async.with_task_group(async fn(group) {
  84	        let child = @process.spawn(
  85	          group,
  86	          program,
  87	          args,
  88	          extra_env?=environment,
  89	          inherit_env=environment is None,
  90	          cwd?,
  91	          stdout~,
  92	          stderr~,
  93	        )
  94	        let output = group.spawn(async fn() {
  95	          progress.read_output(
  96	            out,
  97	            capture=true,
  98	            statuses=devsy_progress_stage(stage),
  99	            messages=stage == "orca-install" || stage == "checkout-workspace",
 100	          )
 101	        })
 102	        let errors = group.spawn(async fn() {
 103	          progress.read_output(
 104	            err,
 105	            capture=false,
 106	            messages=devsy_progress_stage(stage) ||
 107	              stage == "orca-install" ||
 108	              stage == "checkout-workspace",
 109	          )
 110	        })
 111	        (child.wait(), output.wait(), errors.wait())
 112	      })
 113	    } catch {
 114	      @os_error.OSError(code, ..) as error => {
 115	        failure_kind = "process_os"
 116	        failure_errno = Some(code)
 117	        let message = progress
 118	          .safe_message(program + ": " + error.to_string())
 119	          .unwrap_or("subprocess OS error \{code}")
 120	        progress.remember(message, warning=true)
 121	        raise AdapterError(
 122	          "\{stage} failed (OS error \{code}); diagnostic run \{recording_run_id}:\n" +
 123	          message,
 124	        )
 125	      }
 126	      @utf8.Malformed(_) => {
 127	        failure_kind = "process_utf8"
 128	        failure_phase = Some("read")
 129	        progress.remember("subprocess output is not valid UTF-8", warning=true)
 130	        raise AdapterError(
 131	          "\{stage} failed: subprocess output is not valid UTF-8; diagnostic run \{recording_run_id}",
 132	        )
 133	      }
 134	      error => {
 135	        if !@async.is_being_cancelled() {
 136	          let detail = diagnostic_error(error, environment?)
 137	          for line in detail.split("\n") {
 138	            progress.remember(line.to_owned(), warning=true)
 139	          }
 140	        }
 141	        raise error
 142	      }
 143	    }
 144	  }
 145	  progress_message(
 146	    label +
 147	    ": " +
 148	    (if status == 0 { "done" } else { "failed (exit \{status})" }) +
 149	    " (" +
 150	    progress_timing(started) +
 151	    ")",
 152	  )
 153	  save_diagnostic(
 154	    stage,
 155	    if status == 0 {
 156	      "success"
 157	    } else {
 158	      "exit-error"
 159	    },
 160	    exit_code=status,
 161	    duration_ms=(@env.now() - started).to_double(),
 162	    error_message?=if status == 0 {
 163	      None
 164	    } else {
 165	      Some(progress.failure_detail())
 166	    },
 167	    details_truncated=progress.details_truncated,
 168	    error_type?=if status == 0 || !recording {
 169	      None
 170	    } else {
 171	      Some(process_error_type(output + "\n" + errors))
 172	    },
 173	    recording~,
 174	  )
 175	  (status, output, progress.failure_detail())
 176	}
