237	///|
238	async fn Progress::status(self : Progress, event : Json) -> Unit {
239	  guard field(event, "phase") is Some(Json::String(phase)) &&
240	    phase_label(phase) is Some(label) &&
241	    field(event, "state") is Some(Json::String(state)) &&
242	    ["started", "succeeded", "failed", "skipped"].contains(state) else {
243	    return
244	  }
245	  if self.phase_count < 128 {
246	    self.phase_count += 1
247	    save_diagnostic(
248	      self.stage,
249	      state,
250	      phase~,
251	      error_type?=if state == "failed" { Some("backend_phase") } else { None },
252	      recording=self.recording,
253	    )
254	  } else if self.phase_count == 128 {
255	    self.phase_count += 1
256	    save_diagnostic(
257	      self.stage,
258	      "diagnostics-truncated",
259	      error_type="phase_limit",
260	      recording=self.recording,
261	    )
262	  }
263	  let key = ["pipeline", "operationId", "phase", "step"]
264	    .map(name => field(event, name).unwrap_or(Json::null()).stringify())
265	    .join(":")
266	  if state == "started" {
267	    if self.operations.length() >= 256 {
268	      self.operations.clear()
269	    }
270	    self.operations.set(key, @env.now())
271	    progress_message(label + ": running…")
272	  } else {
273	    let duration = match field(event, "durationMs") {
274	      Some(Json::Number(value, ..)) if value >= 0 && value < 864000000 =>
275	        Some(seconds(value.to_uint64()))
276	      _ => self.operations.get(key).map(start => seconds(@env.now() - start))
277	    }
278	    self.operations.remove(key)
279	    let timing = duration.map(value => value + ", ").unwrap_or("") +
280	      "elapsed " +
281	      seconds(@env.now() - progress_started)
282	    progress_message(
283	      label +
284	      ": " +
285	      (if state == "succeeded" { "done" } else { state }) +
286	      " (" +
287	      timing +
288	      ")",
289	    )
290	  }
291	}
