242	async fn supervisor_inner(
243	  directory : String,
244	  initial_workspace? : String,
245	) -> Unit {
246	  publish_file(directory + "/supervisor.pid", proxy_pid().to_string())
247	
248	  let mut released = false
249	  defer (if !released {
250	    @fs.remove(directory + "/supervisor.pid") catch {
251	      _ => ()
252	    }
253	  })
254	  save_diagnostic("supervisor", "started", evidence={
255	    "stateDirectory": directory,
256	  })
257	  defer save_diagnostic("supervisor", "stopped")
258	  let listener = @socket.TcpServer(@socket.Addr::parse("127.0.0.1:0"))
259	  defer listener.close()
260	  let identity : Json = {
261	    "protocol": 1,
262	    "pid": proxy_pid().to_string(),
263	    "start": process_start(proxy_pid()).to_string(),
264	  }
265	  let descriptor : Json = {
266	    "pid": required(identity, "pid"),
267	    "start": required(identity, "start"),
268	    "port": listener.addr.port().to_string(),
269	  }
270	  publish_file(directory + "/supervisor.json", descriptor.stringify())
271	  let environments : Map[String, Map[String, String]] = Map([])
272	  if initial_workspace is Some(workspace) {
273	    let canonical = @fs.realpath(workspace)
274	    guard canonical.has_prefix(@fs.realpath(directory) + "/tunnels/") else {
275	      raise AdapterError("Initial workspace is outside the state directory")
276	    }
277	    let saved = @json.parse(
278	      @fs.read_file(workspace + "/environment.json").text(),
279	    )
280	    guard saved is Json::Object(values) else {
281	      raise AdapterError("Invalid saved workspace environment")
282	    }
283	    let environment : Map[String, String] = Map([])
284	    for (name, value) in values {
285	      guard value is Json::String(value) else {
286	        raise AdapterError("Invalid saved workspace environment")
287	      }
288	      environment.set(name, value)
289	    }
290	    environments.set(canonical, environment)
291	    @fs.write_file(workspace + "/request", "", permission=0o600)
292	  }
293	  let registrations : Ref[Int32] = { val: 0, }
294	  let active : Map[String, Bool] = Map([])
295	  let transports : Map[String, Bool] = Map([])
296	  let mut idle_since = @env.now()
297	  @async.with_task_group(async fn(group) {
298	    group.spawn_bg(no_wait=true, async fn() {
299	      while true {
300	        @async.sleep(250)
301	        if !diagnostic_pending.is_empty() ||
302	          diagnostic_recording_health.dropped > 0 {
303	          try_flush_diagnostic_recording()
304	        }
305	      }
306	    })
307	    let registration_slots = @async.Semaphore(16)
308	    group.spawn_bg(no_wait=true, async fn() {
309	      while true {
310	        registration_slots.acquire()
311	        let (socket, _) = listener.accept()
312	        registrations.val += 1
313	        group.spawn_bg(no_wait=true, async fn() {
314	          defer {
315	            registrations.val -= 1
316	            registration_slots.release()
317	          }
318	          accept_registration(socket, directory, environments, identity) catch {
319	            error =>
320	              save_diagnostic(
321	                "supervisor-registration",
322	                "failed",
323	                error_type="registration_failed",
324	                error_message=diagnostic_error(error),
325	              )
326	          }
327	        })
328	      }
329	    })
330	    while @fs.exists(directory) {
331	      if @fs.exists(directory + "/shutdown") {
332	        return
333	      }
334	      for workspace in environments.keys().to_array() {
335	        if !@fs.exists(workspace) {
336	          environments.remove(workspace)
337	        }
338	      }
339	      let base = directory + "/tunnels"
340	      if @fs.exists(base) {
341	        for name in @fs.readdir(base) {
342	          let workspace = base + "/" + name
343	          try {
344	            let requested = @fs.exists(workspace + "/request")
345	            if !requested {
346	              continue
347	            }
348	            let canonical = @fs.realpath(workspace)
349	            guard environments.get(canonical) is Some(environment) else {
350	              continue
351	            }
352	            if active.contains(workspace) ||
353	              !@fs.exists(workspace + "/enabled") ||
354	              !@fs.exists(workspace + "/state.json") {
355	              continue
356	            }
357	            if requested {
358	              @fs.remove(workspace + "/request")
359	            }
360	            active.set(workspace, true)
361	            diagnostic_workspace_environments.set(workspace, environment)
362	            group.spawn_bg(no_wait=true, async fn() {
363	              defer {
364	                active.remove(workspace)
365	                diagnostic_workspace_environments.remove(workspace)
366	              }
367	              try {
368	                save_diagnostic(
369	                  "supervisor-workspace",
370	                  "started",
371	                  tunnel_directory=workspace,
372	                  recording=environment.get("ORCA_ENV_DEVSY_RECORDING") !=
373	                    Some("0"),
374	                )
375	                if !worker_alive(workspace) {
376	                  tunnel_status(
377	                    workspace,
378	                    "connecting",
379	                    recording=environment.get("ORCA_ENV_DEVSY_RECORDING") !=
380	                      Some("0"),
381	                  )
382	                  git_relay_status(
383	                    workspace,
384	                    "pending",
385	                    recording=environment.get("ORCA_ENV_DEVSY_RECORDING") !=
386	                      Some("0"),
387	                  )
388	                }
389	                tunnel_worker(workspace, environment)
390	                save_diagnostic(
391	                  "supervisor-workspace",
392	                  "stopped",
393	                  tunnel_directory=workspace,
394	                  recording=environment.get("ORCA_ENV_DEVSY_RECORDING") !=
395	                    Some("0"),
396	                )
397	              } catch {
398	                error => {
399	                  save_diagnostic(
400	                    "supervisor-workspace",
401	                    "failed",
402	                    tunnel_directory=workspace,
403	                    error_type="workspace_task_failed",
404	                    error_message=diagnostic_error(error, environment~),
405	                    recording=environment.get("ORCA_ENV_DEVSY_RECORDING") !=
406	                      Some("0"),
407	                  )
408	                  @async.sleep(1000)
409	                }
410	              }
411	            })
412	          } catch {
413	            error =>
414	              save_diagnostic(
415	                "supervisor-workspace",
416	                "failed",
417	                tunnel_directory=workspace,
418	                error_type="workspace_registration_failed",
419	                error_message=diagnostic_error(error),
420	              )
421	          }
422	        }
423	      }
424	      let base = directory + "/transports"
425	      if @fs.exists(base) {
426	        for name in @fs.readdir(base) {
427	          let transport = base + "/" + name
428	          if transports.contains(transport) ||
429	            !@fs.exists(transport + "/state.json") ||
430	            @fs.exists(transport + "/done") {
431	            continue
432	          }
433	          transports.set(transport, true)
434	          group.spawn_bg(no_wait=true, async fn() {
435	            defer transports.remove(transport)
436	            supervise_transport(transport) catch {
437	              error =>
438	                save_diagnostic(
439	                  "supervisor-transport",
440	                  "failed",
441	                  error_type="transport_cleanup_failed",
442	                  error_message=diagnostic_error(error),
443	                )
444	            }
445	          })
446	        }
447	      }
448	      if !active.is_empty() || !transports.is_empty() || registrations.val > 0 {
449	        idle_since = @env.now()
450	      } else if @env.now() - idle_since >= 1000 {
451	        let startup = @fs.open(
452	          directory + "/supervisor-startup.lock",
453	          mode=ReadWrite,
454	          create_mode=OpenOrCreate,
455	          permission=0o600,
456	        )
457	        defer startup.close()
458	        if startup.try_lock(Exclusive) &&
459	          !supervisor_pending(directory, environments) {
460	          listener.close()
461	          @fs.remove(directory + "/supervisor.json")
462	          @fs.remove(directory + "/supervisor.pid")
463	          released = true
464	          return
465	        }
466	      }
467	      @async.sleep(100)
468	    }
469	  })
470	}
